from collections import defaultdict, deque
import itertools

def check_cayley_girth(generators, mod):
    """Check girth of Cayley graph on Z_mod with given generators"""
    n = mod
    adj = defaultdict(set)
    for v in range(n):
        for g in generators:
            u = (v + g) % n
            if u != v:
                adj[v].add(u)

    min_cycle = float('inf')
    for start in range(n):
        dist = {start: 0}
        queue = deque([(start, None)])

        while queue and dist.get(start, 0) < min_cycle:
            u, par = queue.popleft()
            if dist[u] + 1 >= min_cycle:
                continue
            for g in generators:
                v = (u + g) % n
                if v == par:
                    continue
                if v == start:
                    min_cycle = min(min_cycle, dist[u] + 1)
                elif v not in dist:
                    dist[v] = dist[u] + 1
                    queue.append((v, u))
                else:
                    cycle_len = dist[u] + dist[v] + 1
                    min_cycle = min(min_cycle, cycle_len)

    return min_cycle

# Pairs for Z_19
pairs = [(1,18), (2,17), (3,16), (4,15), (5,14), (6,13), (7,12), (8,11), (9,10)]

best_girth = 0
best_gens = None
best_edges = 0

for r in range(1, len(pairs)+1):
    for combo in itertools.combinations(pairs, r):
        gens = []
        for p in combo:
            gens.extend(p)

        g = check_cayley_girth(gens, 19)
        num_edges = 19 * len(gens) // 2

        if g >= 7:
            print(f"Generators {gens}: girth {g}, degree {len(gens)}, edges {num_edges}")
            if num_edges > best_edges:
                best_edges = num_edges
                best_girth = g
                best_gens = gens[:]

    if best_edges >= 32:
        print(f"Found enough edges!")
        break

print(f"\nBest: generators {best_gens}, girth {best_girth}, edges {best_edges}")

