from collections import defaultdict, deque
import itertools

def check_cayley_girth_fast(generators, mod):
    """Check girth of Cayley graph on Z_mod with given generators"""
    n = mod

    min_cycle = float('inf')
    for start in range(n):
        dist = [-1] * n
        dist[start] = 0
        queue = deque([(start, -1)])

        while queue:
            u, par = queue.popleft()
            if dist[u] + 1 >= min_cycle:
                continue
            for g in generators:
                v = (u + g) % n
                if v == par:
                    continue
                if v == start:
                    min_cycle = min(min_cycle, dist[u] + 1)
                elif dist[v] == -1:
                    dist[v] = dist[u] + 1
                    queue.append((v, u))
                else:
                    cycle_len = dist[u] + dist[v] + 1
                    min_cycle = min(min_cycle, cycle_len)

    return min_cycle

